 v_esperada=v_datos#>>'{metadatos,partes,fuentes_0013,sha256}';
 if v_datos#>>'{metadatos,lote}' is distinct from '76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' or v_esperada is distinct from '29bc220f90ebfb1c83a4c524066f58dc92070f80bbd60cb2c4ec3a4d2086c1e2'
 or encode(sha256(convert_to(v_fragmento,'UTF8')),'hex') is distinct from v_esperada then
  raise exception 'Fragmento fuentes_0013 incorrecto; no se guardó';
 end if;
 update public.s911_catalogos set fuentes=jsonb_set(fuentes,'{fragmentos,fuentes_0013}',to_jsonb(v_fragmento),true)
 where sha256='CARGA911:76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' and edicion='CARGA_2026-2027';
end $parte911$;
select 'PARTE_013_OK' estado,
 (select count(*) from jsonb_object_keys(fuentes->'fragmentos')) partes_recibidas,
 33 partes_esperadas
from public.s911_catalogos where sha256='CARGA911:76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' and edicion='CARGA_2026-2027';

commit;
